CREATE OR REPLACE FUNCTION public.fn_agenda_excepciones_sucursal_bloques_validar_modo()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_modo text;
BEGIN
  SELECT e.modo_excepcion_codigo
    INTO v_modo
  FROM public.agenda_excepciones_sucursal e
  WHERE e.id_excepcion_sucursal = NEW.id_excepcion_sucursal;

  IF v_modo IS NULL THEN
    RAISE EXCEPTION 'La excepción de sucursal no existe.'
      USING ERRCODE = '23503';
  END IF;

  IF v_modo = 'cierre_total' THEN
    RAISE EXCEPTION 'cierre_total no permite bloques horarios.'
      USING ERRCODE = '23514';
  END IF;

  IF v_modo NOT IN ('cierre_parcial', 'horario_especial', 'apertura_extra') THEN
    RAISE EXCEPTION 'Modo de excepción de sucursal no soporta bloques horarios.'
      USING ERRCODE = '23514';
  END IF;

  RETURN NEW;
END;
$function$

