CREATE OR REPLACE FUNCTION public.fn_agenda_excepciones_sucursal_validar_compatibilidad()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.modo_excepcion_codigo = 'cierre_total' THEN
    IF EXISTS (
      SELECT 1
      FROM public.agenda_excepciones_sucursal e
      WHERE e.id_sucursal = NEW.id_sucursal
        AND e.fecha = NEW.fecha
        AND e.id_excepcion_sucursal <> NEW.id_excepcion_sucursal
    ) THEN
      RAISE EXCEPTION 'No se puede registrar cierre_total junto con otras excepciones de sucursal para la misma fecha.'
        USING ERRCODE = '23514';
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1
      FROM public.agenda_excepciones_sucursal e
      WHERE e.id_sucursal = NEW.id_sucursal
        AND e.fecha = NEW.fecha
        AND e.id_excepcion_sucursal <> NEW.id_excepcion_sucursal
        AND e.modo_excepcion_codigo = 'cierre_total'
    ) THEN
      RAISE EXCEPTION 'No se puede registrar una excepción de sucursal cuando ya existe cierre_total para la misma fecha.'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.modo_excepcion_codigo IN ('horario_especial', 'apertura_extra') THEN
    IF EXISTS (
      SELECT 1
      FROM public.agenda_excepciones_sucursal e
      WHERE e.id_sucursal = NEW.id_sucursal
        AND e.fecha = NEW.fecha
        AND e.id_excepcion_sucursal <> NEW.id_excepcion_sucursal
        AND e.modo_excepcion_codigo IN ('horario_especial', 'apertura_extra')
    ) THEN
      RAISE EXCEPTION 'No se puede combinar horario_especial y apertura_extra en la misma sucursal y fecha.'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  IF NEW.modo_excepcion_codigo = 'cierre_total' THEN
    IF EXISTS (
      SELECT 1
      FROM public.agenda_excepciones_sucursal_bloques b
      WHERE b.id_excepcion_sucursal = NEW.id_excepcion_sucursal
    ) THEN
      RAISE EXCEPTION 'cierre_total no debe tener bloques horarios.'
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END;
