    IF EXISTS (
      SELECT 1
      FROM public.empleados e
      WHERE e.id_persona = NEW.id_persona
        AND e.deleted_at IS NULL
    ) THEN
      RAISE EXCEPTION 'La persona ya existe como empleado y no puede crearse como cliente';
    END IF;
  END IF;

  RETURN NEW;
END;
