CREATE OR REPLACE FUNCTION public.fn_citas_integrantes_validate_limits()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_total_integrantes integer;
  v_total_acompanantes integer;
BEGIN
  SELECT COUNT(*)
  INTO v_total_integrantes
  FROM public.citas_integrantes ci
  WHERE ci.id_grupo_cita = NEW.id_grupo_cita
    AND ci.id_cita_integrante <> NEW.id_cita_integrante;

  IF v_total_integrantes >= 5 THEN
    RAISE EXCEPTION 'MAX_INTEGRANTES_GRUPO_EXCEEDED';
  END IF;

  IF NEW.rol_integrante_codigo = 'acompanante' THEN
    SELECT COUNT(*)
    INTO v_total_acompanantes
    FROM public.citas_integrantes ci
    WHERE ci.id_grupo_cita = NEW.id_grupo_cita
      AND ci.rol_integrante_codigo = 'acompanante'
      AND ci.id_cita_integrante <> NEW.id_cita_integrante;

    IF v_total_acompanantes >= 4 THEN
      RAISE EXCEPTION 'MAX_ACOMPANANTES_EXCEEDED';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

