CREATE OR REPLACE FUNCTION public.fn_guardar_desactivacion_servicio()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.activo = TRUE AND NEW.activo = FALSE THEN

    IF EXISTS (
      SELECT 1
      FROM public.paquetes_detalles pd
      JOIN public.paquetes p
        ON p.id_paquete = pd.id_paquete
      WHERE pd.id_servicio = OLD.id_servicio
        AND p.deleted_at IS NULL
        AND p.activo = TRUE
    ) THEN
      RAISE EXCEPTION 'No se puede desactivar el servicio porque está ligado a paquetes activos. Debe quitarse primero de esos paquetes.';
    END IF;

    IF EXISTS (
      SELECT 1
      FROM public.points_rule_services prs
      JOIN public.points_rules pr
        ON pr.id_rule = prs.id_rule
      WHERE prs.id_servicio = OLD.id_servicio
        AND pr.activo = TRUE
    ) THEN
      RAISE EXCEPTION 'No se puede desactivar el servicio porque está ligado a reglas activas. Debe quitarse primero de esas reglas.';
    END IF;

    NEW.agendable := FALSE;
    NEW.visible_publico := FALSE;
  END IF;

  RETURN NEW;
END;
$function$

