  IF v_nombre_rol IN ('super_admin', 'cliente', 'root') THEN
    IF NEW.id_sucursal IS NOT NULL THEN
      RAISE EXCEPTION 'ROL_GLOBAL_NO_DEBE_TENER_SUCURSAL';
