    WHERE ru.id_rol = NEW.id_rol
      AND ru.id_usuario = NEW.id_usuario
      AND ru.id_sucursal IS NOT DISTINCT FROM NEW.id_sucursal
      AND (TG_OP = 'INSERT' OR ru.id_rol_usuario <> NEW.id_rol_usuario)
  )
  INTO v_existe;

  IF v_existe THEN
    RAISE EXCEPTION 'ROL_USUARIO_DUPLICADO_MISMO_SCOPE';
  END IF;

  RETURN NEW;
END;
