CREATE OR REPLACE FUNCTION public.fn_validar_persona_empleado_campos_obligatorios()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_dni text;
  v_telefono text;
  v_existe_empleado_activo boolean;
BEGIN
  -- Caso A: se inserta/actualiza empleado
  IF TG_TABLE_NAME = 'empleados' THEN
    -- Si el registro de empleado se está soft-deleteando, no validar
    IF NEW.deleted_at IS NOT NULL THEN
      RETURN NEW;
    END IF;

    SELECT
      regexp_replace(COALESCE(p.dni, ''), '\D', '', 'g'),
      BTRIM(COALESCE(p.telefono_principal, ''))
    INTO
      v_dni,
      v_telefono
    FROM public.personas p
    WHERE p.id_persona = NEW.id_persona
      AND p.deleted_at IS NULL;

    IF NOT FOUND THEN
      RAISE EXCEPTION
        USING ERRCODE = '23514',
              MESSAGE = 'No se puede crear/actualizar empleado: la persona asociada no existe o está eliminada.';
    END IF;

    IF v_dni = '' THEN
      RAISE EXCEPTION
        USING ERRCODE = '23514',
              MESSAGE = 'No se puede crear/actualizar empleado: el DNI es obligatorio para empleados.';
    END IF;

    IF v_telefono = '' THEN
      RAISE EXCEPTION
        USING ERRCODE = '23514',
              MESSAGE = 'No se puede crear/actualizar empleado: el teléfono principal es obligatorio para empleados.';
    END IF;

    RETURN NEW;
  END IF;

  -- Caso B: se actualiza persona que ya está vinculada a un empleado activo
  IF TG_TABLE_NAME = 'personas' THEN
    SELECT EXISTS (
      SELECT 1
      FROM public.empleados e
      WHERE e.id_persona = NEW.id_persona
        AND e.deleted_at IS NULL
    )
    INTO v_existe_empleado_activo;

    IF v_existe_empleado_activo THEN
      IF regexp_replace(COALESCE(NEW.dni, ''), '\D', '', 'g') = '' THEN
        RAISE EXCEPTION
          USING ERRCODE = '23514',
                MESSAGE = 'No se puede actualizar la persona: el DNI es obligatorio porque está vinculada a un empleado activo.';
      END IF;

      IF BTRIM(COALESCE(NEW.telefono_principal, '')) = '' THEN
        RAISE EXCEPTION
          USING ERRCODE = '23514',
                MESSAGE = 'No se puede actualizar la persona: el teléfono principal es obligatorio porque está vinculada a un empleado activo.';
      END IF;
    END IF;

    RETURN NEW;
  END IF;

  RETURN NEW;
END;
