CREATE OR REPLACE FUNCTION public.validate_membership_plan_beneficios()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  servicios_count INT;
BEGIN
  IF NEW.beneficios IS NULL THEN
    RAISE EXCEPTION 'PLAN_BENEFICIOS_REQUIRED';
  END IF;

  -- Validar que exista array de servicios
  IF NOT (NEW.beneficios ? 'servicios') THEN
    RAISE EXCEPTION 'PLAN_SERVICIOS_REQUIRED';
  END IF;

  SELECT jsonb_array_length(NEW.beneficios->'servicios')
  INTO servicios_count;

  IF servicios_count < 1 THEN
    RAISE EXCEPTION 'PLAN_SERVICIOS_MIN_REQUIRED';
  END IF;

  RETURN NEW;
END;
