CREATE OR REPLACE FUNCTION public.fn_citas_detalles_line_identity_v2()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_orden_integrante integer;
  v_next_order integer;
  v_occurrence integer;
  v_expected_key text;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.id_cita IS DISTINCT FROM OLD.id_cita
       OR NEW.id_servicio IS DISTINCT FROM OLD.id_servicio
       OR NEW.id_tarifa IS DISTINCT FROM OLD.id_tarifa
       OR NEW.origen_item_codigo IS DISTINCT FROM OLD.origen_item_codigo
       OR NEW.orden_linea IS DISTINCT FROM OLD.orden_linea
       OR NEW.line_key IS DISTINCT FROM OLD.line_key THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'MF_BOOKING_LINE_IDENTITY_IMMUTABLE';
    END IF;
    RETURN NEW;
  END IF;

  SELECT COALESCE(c.orden_integrante, 1)
  INTO v_orden_integrante
  FROM public.citas c
  WHERE c.id_cita = NEW.id_cita;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '23503',
      MESSAGE = 'MF_BOOKING_LINE_APPOINTMENT_NOT_FOUND';
  END IF;

  IF NEW.orden_linea IS NULL OR NEW.orden_linea < 1 THEN
    SELECT COALESCE(max(cd.orden_linea), 0) + 1
    INTO v_next_order
    FROM public.citas_detalles cd
    WHERE cd.id_cita = NEW.id_cita;
    NEW.orden_linea := GREATEST(1, COALESCE(v_next_order, 1));
  END IF;

  SELECT count(*)::integer + 1
  INTO v_occurrence
  FROM public.citas_detalles cd
  WHERE cd.id_cita = NEW.id_cita
    AND cd.id_servicio = NEW.id_servicio
    AND cd.id_tarifa IS NOT DISTINCT FROM NEW.id_tarifa
    AND cd.origen_item_codigo = NEW.origen_item_codigo;

  v_expected_key := app_private.build_booking_line_key_v1(
    v_orden_integrante,
    NEW.id_servicio,
    NEW.id_tarifa,
    NEW.origen_item_codigo,
    v_occurrence
  );

  IF NULLIF(btrim(NEW.line_key), '') IS NULL THEN
    NEW.line_key := v_expected_key;
  ELSIF NEW.line_key IS DISTINCT FROM v_expected_key THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0001',
      MESSAGE = 'MF_BOOKING_LINE_KEY_MISMATCH',
      DETAIL = format('expected=%s received=%s', v_expected_key, NEW.line_key);
  END IF;

  RETURN NEW;
END;
$function$

